_RETRY_STATUSES = frozenset({408, 429, 500, 502, 503, 504})
_BODYLESS_STATUSES = frozenset({204, 205, 304})
_MAX_ATTEMPTS = 10
_MAX_SECONDS = 2_147_483.647
_TOKEN = re.compile(r"[!#$%&'*+\-.^_`|~0-9A-Za-z]+")
_HEADER_INVALID = re.compile(r"[^\t\x20-\x7e\x80-\xff]")
_RESERVED = re.compile(r"%(3A|2F|3F|5B|5D|40|21|24|26|27|28|29|2A|2B|2C|3B|3D)", re.IGNORECASE)
_ENCODED_PERCENT = re.compile(r"%25([0-9A-Fa-f]{2})")
_MALFORMED_PERCENT = re.compile(r"%(?![0-9A-Fa-f]{2})")
_DOT_SEGMENTS = frozenset({".", "..", "%2e", "%2e%2e", ".%2e", "%2e."})


class _InputError(Exception):
    """Invalid input, found before anything is sent: a validation failure."""


def _seconds(value: object, name: str, minimum: float, exclusive: bool) -> float:
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        try:
            number = float(value)
        except OverflowError:
            number = math.inf
        if math.isfinite(number) and number <= _MAX_SECONDS and (number > minimum if exclusive else number >= minimum):
            return number
    relation = "greater than" if exclusive else "at least"
    raise ValueError(f"{name} must be a number of seconds {relation} {minimum:g} and at most {_MAX_SECONDS:g}.")


def _resolve_retry(base: RetryPolicy, override: object) -> RetryPolicy:
    if override is None:
        return base
    if not isinstance(override, Mapping):
        raise ValueError("retry must be a mapping with max_attempts, base_delay and max_delay.")
    unknown = sorted(str(key) for key in override if key not in ("max_attempts", "base_delay", "max_delay"))
    if unknown:
        raise ValueError(f"retry has unknown options: {', '.join(unknown)}.")
    attempts = override.get("max_attempts", base.max_attempts)
    if isinstance(attempts, bool) or not isinstance(attempts, int) or not 1 <= attempts <= _MAX_ATTEMPTS:
        raise ValueError(f"retry.max_attempts must be an integer from 1 to {_MAX_ATTEMPTS}.")
    base_delay = _seconds(override["base_delay"], "retry.base_delay", 0, False) if "base_delay" in override else base.base_delay
    max_delay = _seconds(override["max_delay"], "retry.max_delay", 0, False) if "max_delay" in override else base.max_delay
    return RetryPolicy(attempts, base_delay, max_delay)


def _trim_slashes(value: str) -> str:
    return value.rstrip("/")


def _parse_base_url(value: object) -> str:
    """An absolute http(s) URL of printable ASCII without user info, query, fragment or dot segments, trimmed of trailing "/"."""
    if not isinstance(value, str) or not re.fullmatch(r"[\x21-\x7e]+", value) or "\\" in value:
        raise ValueError("base_url must be an absolute http or https URL of printable ASCII.")
    parts = urlsplit(value)
    if parts.scheme.lower() not in ("http", "https") or not parts.netloc or not parts.hostname:
        raise ValueError("base_url must be an absolute http or https URL.")
    if "@" in parts.netloc:
        raise ValueError("base_url must not contain user info; pass credentials through the credentials option.")
    if "?" in value or "#" in value:
        raise ValueError("base_url must not contain a query or fragment.")
    try:
        port = parts.port
    except ValueError as error:
        raise ValueError(f"base_url has an invalid port: {error}") from None
    if port == 0:
        raise ValueError("base_url has an invalid port: 0.")
    if any(segment.lower() in _DOT_SEGMENTS for segment in parts.path.split("/")):
        raise ValueError("base_url must not contain dot segments.")
    return _trim_slashes(f"{parts.scheme.lower()}://{parts.netloc.lower()}{parts.path}")


def _encode(value: str, allow_reserved: bool = False) -> str:
    """RFC 3986 unreserved characters stay as they are; everything else is percent-encoded as UTF-8."""
    try:
        encoded = quote(value, safe="", encoding="utf-8", errors="strict")
    except UnicodeEncodeError as error:
        raise _InputError(f"A parameter or credential value cannot be encoded as UTF-8: {error.reason}.") from None
    if not allow_reserved:
        return encoded
    # Reserved expansion: keep RFC 3986 reserved characters and existing percent-encoded triples, except "#",
    # which would end the query.
    encoded = _RESERVED.sub(lambda match: chr(int(match.group(1), 16)), encoded)
    return _ENCODED_PERCENT.sub(r"%\1", encoded)


def _number_text(value: float) -> str:
    """A finite float as JavaScript's Number#toString writes it, so both clients send the same text."""
    if value == 0:
        return "0"
    if value < 0:
        return f"-{_number_text(-value)}"
    mantissa, _, exponent = repr(value).partition("e")
    whole, _, fraction = mantissa.partition(".")
    combined = whole + fraction
    significant = combined.lstrip("0")
    point = len(whole) + (int(exponent) if exponent else 0) - (len(combined) - len(significant))
    digits = significant.rstrip("0")
    count = len(digits)
    if count <= point <= 21:
        return digits + "0" * (point - count)
    if 0 < point <= 21:
        return f"{digits[:point]}.{digits[point:]}"
    if -6 < point <= 0:
        return f"0.{'0' * -point}{digits}"
    power = point - 1
    head = digits[0] + (f".{digits[1:]}" if count > 1 else "")
    return f"{head}e{'+' if power >= 0 else '-'}{abs(power)}"


def _primitive(value: object, where: str) -> str:
    if isinstance(value, str):
        return str.__str__(value)
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return int.__repr__(value)
    if isinstance(value, float) and math.isfinite(value):
        return _number_text(float(value))
    raise _InputError(f"{where} must be a string, finite number or boolean.")


def _is_array_index(key: str) -> bool:
    return key.isascii() and key.isdigit() and (key == "0" or key[0] != "0") and int(key) < 4_294_967_295


def _ordered_keys(mapping: Mapping[Any, object], where: str) -> list[str]:
    """Keys in the order JavaScript enumerates an object's: array indexes ascending, then the rest in order."""
    keys: list[str] = []
    for key in mapping:
        if not isinstance(key, str):
            raise _InputError(f"{where} must have string keys.")
        keys.append(key)
    return sorted((key for key in keys if _is_array_index(key)), key=int) + [key for key in keys if not _is_array_index(key)]


def _is_sequence(value: object) -> TypeGuard[Sequence[object]]:
    return isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray, memoryview))


@dataclass
class _Members:
    """A parameter value flattened: `values` for a scalar or array, `pairs` (name, value) for a mapping."""

    values: list[str]
    pairs: list[tuple[str, str]] | None


def _members(value: object, where: str) -> _Members:
    if _is_sequence(value):
        return _Members([_primitive(item, f"{where}[{index}]") for index, item in enumerate(value)], None)
    if isinstance(value, Mapping):
        pairs = [(key, _primitive(value[key], f"{where}.{key}")) for key in _ordered_keys(value, where) if value[key] is not None]
        return _Members([], pairs)
    return _Members([_primitive(value, where)], None)


def _simple(value: object, explode: bool, where: str, encode: Callable[[str], str]) -> str:
    parts = _members(value, where)
    if parts.pairs is not None:
        separator = "=" if explode else ","
        return ",".join(f"{encode(key)}{separator}{encode(item)}" for key, item in parts.pairs)
    return ",".join(encode(item) for item in parts.values)


def _query_pairs(spec: ParameterSpec, value: object, where: str) -> list[str]:
    def encode(text: str) -> str:
        return _encode(text, spec.allow_reserved)

    name = _encode(spec.name)
    if spec.style == "deepObject":
        if not isinstance(value, Mapping):
            raise _InputError(f"{where} must be a mapping for deepObject serialization.")
        return [f"{name}[{_encode(key)}]={encode(item)}" for key, item in _members(value, where).pairs or []]
    parts = _members(value, where)
    if parts.pairs:
        if spec.explode:
            return [f"{_encode(key)}={encode(item)}" for key, item in parts.pairs]
        return [f"{name}=" + ",".join(f"{encode(key)},{encode(item)}" for key, item in parts.pairs)]
    if _is_sequence(value) and not parts.values:
        return []
    if spec.explode:
        return [f"{name}={encode(item)}" for item in parts.values]
    return [f"{name}=" + ",".join(encode(item) for item in parts.values)]


def _pair_name(pair: str) -> str:
    """The name of a query pair as a server decodes it (form encoding: "+" is a space)."""
    raw = pair.split("=", 1)[0].replace("+", " ")
    if _MALFORMED_PERCENT.search(raw):
        return raw
    try:
        return unquote(raw, encoding="utf-8", errors="strict")
    except UnicodeDecodeError:
        return raw


def _supplies(term: SecurityTerm, spec: ParameterSpec) -> bool:
    """Whether an API key credential is sent under a parameter's name and location (header names ignore case)."""
    if term.type != "apiKey" or term.location != spec.location or term.name is None:
        return False
    return term.name.lower() == spec.name.lower() if term.location == "header" else term.name == spec.name


def _header_value(value: str, where: str) -> str:
    # Latin-1 text without control characters (tabs allowed); surrounding whitespace is trimmed, as fetch does.
    if _HEADER_INVALID.search(value):
        raise _InputError(f"{where} must not contain control characters or characters outside Latin-1.")
    return value.strip(" \t")


class _HeaderBag:
    """Request headers; setting a name replaces any value under it, ignoring case."""

    def __init__(self) -> None:
        self._values: dict[str, tuple[str, str]] = {}

    def set(self, name: str, value: str, where: str) -> None:
        if not _TOKEN.fullmatch(name):
            raise _InputError(f"{where} cannot be sent as header {name!r}: not a valid header name.")
        self._values[name.lower()] = (name, value)

    def items(self) -> tuple[tuple[str, str], ...]:
        return tuple(self._values.values())


def _json_body(value: object) -> bytes:
    try:
        text = json.dumps(value, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
    except (TypeError, ValueError, RecursionError) as error:
        raise _InputError(f"Parameter body must be JSON-serializable: {error}") from None
    try:
        return text.encode("utf-8")
    except UnicodeEncodeError:
        # An unpaired surrogate: escaped, as JSON.stringify writes it.
        return json.dumps(value, allow_nan=False, separators=(",", ":")).encode("ascii")


async def _resolve(source: object) -> object:
    value = source() if callable(source) else source
    return await value if inspect.isawaitable(value) else value


def _is_json(media_type: str) -> bool:
    return media_type == "application/json" or (media_type.startswith("application/") and media_type.endswith("+json"))


def _retry_after(headers: Headers) -> float | None:
    """Seconds asked for by Retry-After (seconds or an HTTP date); None when absent or unreadable."""
    value = headers.get("retry-after")
    if value is None:
        return None
    text = value.strip()
    if re.fullmatch(r"[0-9]+", text):
        return float(text) if len(text) <= 15 else math.inf
    try:
        when = parsedate_to_datetime(text)
    except (TypeError, ValueError, IndexError):
        return None
    if when.tzinfo is None:
        when = when.replace(tzinfo=timezone.utc)
    return max(0.0, (when - datetime.now(timezone.utc)).total_seconds())


@dataclass
class _Decoded:
    """`empty` marks the empty value of a text or binary media type, which may instead be documented as no content;
    `malformed` marks text of a JSON media type that does not parse."""

    kind: BodyKind
    value: object
    empty: bool = False
    malformed: bool = False


_NO_CONTENT = _Decoded("none", None)


def _reject_constant(name: str) -> object:
    raise ValueError(f"{name} is not JSON")


def _decode(status: int, headers: Headers, data: bytes, method: str) -> _Decoded:
    """Classifies a whole body by media type. An empty body is no content for HEAD, 204, 205, 304, a missing media
    type and JSON (an empty JSON body is not a JSON document); for a text or binary media type it is an empty string
    or bytes marked `empty`, which `_as_documented` turns into no content when the status documents none."""
    media_type = headers.get("content-type", "").split(";")[0].strip().lower()
    if not data:
        if method == "HEAD" or status in _BODYLESS_STATUSES or media_type == "" or _is_json(media_type):
            return _NO_CONTENT
        return _Decoded("text", "", True) if media_type.startswith("text/") else _Decoded("binary", b"", True)
    if _is_json(media_type):
        text = data.decode("utf-8-sig", errors="replace")
        try:
            return _Decoded("json", json.loads(text, parse_constant=_reject_constant))
        except (ValueError, RecursionError):
            return _Decoded("text", text, malformed=True)
    if media_type.startswith("text/"):
        return _Decoded("text", data.decode("utf-8-sig", errors="replace"))
    return _Decoded("binary", data)


def _as_documented(body: _Decoded, kinds: Sequence[BodyKind]) -> _Decoded:
    """Reads an empty text or binary body as no content when the documented kinds include it."""
    return _NO_CONTENT if body.empty and "none" in kinds else body


class _TimedOut(Exception):
    pass


class _TransportFailure(Exception):
    pass


class _Abandonment:
    """The state of a bounded task. Once it is given up, a transport that ignored cancellation is not read any
    further, and the response it returned is closed at once rather than when the task gets round to it."""

    def __init__(self) -> None:
        self.abandoned = False
        self._response: TransportResponse | None = None
        self._closing: asyncio.Future[None] | None = None

    def hold(self, response: TransportResponse) -> None:
        """Records a received response, which `close` or `abandon` closes."""
        self._response = response

    def _start_closing(self) -> asyncio.Future[None] | None:
        """Closes the held response exactly once, as its own task: giving the attempt up cancels the attempt's task,
        never the close, so a close that has started always runs to completion."""
        if self._closing is None and self._response is not None:
            response, self._response = self._response, None
            self._closing = asyncio.ensure_future(_close(response))
            _PENDING.add(self._closing)
            self._closing.add_done_callback(_settled)
        return self._closing

    async def close(self) -> None:
        """Closes the response, or waits for the close `abandon` started; cancelling the wait leaves the close running."""
        closing = self._start_closing()
        if closing is not None:
            await asyncio.shield(closing)

    def abandon(self) -> None:
        self.abandoned = True
        # In the background: a body or close that ignores cancellation must not hold the call, nor keep its response open.
        self._start_closing()


# Tasks given up but not yet finished, and observer tasks, held so they are not collected while pending.
_PENDING: set[asyncio.Future[Any]] = set()


def _settled(task: asyncio.Future[Any]) -> None:
    _PENDING.discard(task)
    if not task.cancelled():
        task.exception()


def _abandon(task: asyncio.Future[Any], state: _Abandonment) -> None:
    task.cancel()
    state.abandon()
    _PENDING.add(task)
    task.add_done_callback(_settled)


async def _bounded(run: Callable[[_Abandonment], Coroutine[Any, Any, _T]], timeout: float) -> _T:
    """Runs `run` as its own task for at most `timeout` seconds. On timeout, or when the caller is cancelled, the task
    is cancelled and given up at once, so a transport or credential provider that ignores cancellation cannot hold
    the call."""
    state = _Abandonment()
    task = asyncio.ensure_future(run(state))
    try:
        done, _ = await asyncio.wait({task}, timeout=timeout)
    except BaseException:
        _abandon(task, state)
        raise
    if task not in done:
        _abandon(task, state)
        raise _TimedOut()
    return task.result()


async def _read_body(body: bytes | AsyncIterable[bytes], state: _Abandonment) -> bytes:
    if isinstance(body, (bytes, bytearray, memoryview)):
        return bytes(body)
    chunks = bytearray()
    async for chunk in body:
        if state.abandoned:
            break
        chunks += chunk
    return bytes(chunks)


async def _close(response: TransportResponse) -> None:
    if response.close is not None:
        try:
            await response.close()
        except Exception:
            pass


@dataclass(frozen=True)
class _Prepared:
    url: str
    headers: tuple[tuple[str, str], ...]
    content: bytes | AsyncIterable[bytes] | None
    replayable: bool


@dataclass
class _Outcome:
    value: object = None
    error: ApiError | None = None
    retryable: bool = False
    retry_after: float | None = None


def _event_id() -> str:
    return f"evt_{secrets.token_hex(12)}"


def _now() -> str:
    now = datetime.now(timezone.utc)
    return f"{now.strftime('%Y-%m-%dT%H:%M:%S')}.{now.microsecond // 1000:03d}Z"


def _drain(awaitable: Awaitable[object]) -> None:
    """Awaits what an observer returned in the background, ignoring its failure."""

    async def run() -> None:
        try:
            await awaitable
        except Exception:
            pass

    task = asyncio.ensure_future(run())
    _PENDING.add(task)
    task.add_done_callback(_settled)


class ApiRuntime:
    """Executes generated operations. Internal: generated clients construct it."""

    def __init__(
        self,
        meta: SdkMetadata,
        *,
        base_url: str | None,
        transport: Transport | None,
        credentials: Mapping[str, object] | None,
        timeout: float | None,
        retry: RetryOptions | None,
        on_failure: Callable[[ClientFailureObservation], object] | None,
    ) -> None:
        self._meta = meta
        url = base_url if base_url is not None else meta.default_base_url
        if url is None:
            raise ValueError("base_url is required: this SDK was generated without a default base URL.")
        self._base = _parse_base_url(url)
        if credentials is not None and (not isinstance(credentials, Mapping) or not all(isinstance(key, str) for key in credentials)):
            raise ValueError("credentials must be a mapping from security scheme names to credentials.")
        self._credentials: dict[str, object] = dict(credentials or {})
        self._timeout = _seconds(timeout, "timeout", 0, True) if timeout is not None else meta.default_timeout
        self._retry = _resolve_retry(meta.default_retry, retry)
        if on_failure is not None and not callable(on_failure):
            raise ValueError("on_failure must be callable.")
        self._on_failure = on_failure
        self._owned_transport: HttpxTransport | None = None
        if transport is None:
            self._owned_transport = HttpxTransport()
            self._transport: Transport = self._owned_transport
        elif callable(transport):
            self._transport = transport
        else:
            raise ValueError("transport must be an async callable taking a TransportRequest.")

    async def aclose(self) -> None:
        if self._owned_transport is not None:
            await self._owned_transport.aclose()

    async def request(self, op: OperationSpec, values: Mapping[str, object], options: RequestOptions | None = None) -> Any:
        attempts = 0
        retryable = False
        try:
            timeout, retry = self._settings(options)
            try:
                prepared = await _bounded(lambda state: self._prepare(op, values), timeout)
            except _TimedOut:
                raise ApiTimeoutError(op.id, f"{op.method} {op.path} timed out after {timeout:g} s.", attempts) from None
            # Only reads and declared-idempotent writes are retried, and never with a body sent as a stream.
            eligible = op.retry != "never" and prepared.replayable
            budget = retry.max_attempts if eligible else 1
            while True:
                attempts += 1
                retryable = False
                outcome = await self._attempt(op, prepared, timeout, attempts)
                if outcome.error is None:
                    return outcome.value
                retryable = eligible and outcome.retryable
                if not retryable or attempts >= budget:
                    raise outcome.error
                backoff = min(retry.max_delay, retry.base_delay * 2 ** (attempts - 1))
                await asyncio.sleep(min(retry.max_delay, outcome.retry_after if outcome.retry_after is not None else backoff))
        except asyncio.CancelledError:
            # Cancellation is the caller's to see: it propagates unchanged and is observed as aborted, never retryable.
            self._observe(op, ApiError("aborted", op.id, f"{op.method} {op.path} was cancelled.", attempts), False)
            raise
        except ApiError as error:
            self._observe(op, error, retryable)
            raise
        except _InputError as error:
            failure = ApiError("validation", op.id, str(error), attempts)
            self._observe(op, failure, False)
            raise failure from error
        except Exception as error:
            failure = ApiError("unknown", op.id, f"{op.method} {op.path} failed.", attempts)
            self._observe(op, failure, False)
            raise failure from error

    def _settings(self, options: RequestOptions | None) -> tuple[float, RetryPolicy]:
        if options is None:
            return self._timeout, self._retry
        if not isinstance(options, Mapping):
            raise _InputError("request_options must be a mapping with timeout and retry.")
        unknown = sorted(str(key) for key in options if key not in ("timeout", "retry"))
        if unknown:
            raise _InputError(f"request_options has unknown options: {', '.join(unknown)}.")
        try:
            timeout = _seconds(options["timeout"], "timeout", 0, True) if "timeout" in options else self._timeout
            return timeout, _resolve_retry(self._retry, options.get("retry"))
        except ValueError as error:
            raise _InputError(str(error)) from None

    async def _prepare(self, op: OperationSpec, values: Mapping[str, object]) -> _Prepared:
        headers = _HeaderBag()
        query: list[str] = []
        path = op.path
        # A required parameter an API key credential can supply is checked once the credential is chosen.
        pending: list[ParameterSpec] = []
        for spec in op.parameters:
            value = values.get(spec.key)
            where = f"Parameter {spec.key}"
            if value is None:
                if spec.required and any(_supplies(term, spec) for terms in op.security for term in terms):
                    pending.append(spec)
                elif spec.required:
                    raise _InputError(f"{where} is required.")
                continue
            if spec.location == "path":
                segment = _simple(value, spec.explode, where, _encode)
                # Dot segments would be removed by URL normalization and move the request to another path.
                if segment in ("", ".", ".."):
                    raise _InputError(f'{where} must be a non-empty path segment other than "." or "..".')
                path = path.replace(f"{{{spec.name}}}", segment)
            elif spec.location == "query":
                query.extend(_query_pairs(spec, value, where))
            else:
                headers.set(spec.name, _header_value(_simple(value, spec.explode, where, lambda text: text), where), where)
        content: bytes | AsyncIterable[bytes] | None = None
        replayable = True
        if op.body is not None:
            body = values.get("body")
            if body is None and not op.body.required:
                pass
            elif op.body.kind == "json":
                content = _json_body(body)
            elif op.body.kind == "text":
                if not isinstance(body, str):
                    raise _InputError("Parameter body must be a str.")
                content = _text_body(body)
            elif isinstance(body, (bytes, bytearray, memoryview)):
                content = bytes(body)
            elif isinstance(body, AsyncIterable):
                content = body
                replayable = False
            else:
                raise _InputError("Parameter body must be bytes, a bytearray, a memoryview or an async iterable of bytes.")
            if content is not None:
                headers.set("content-type", op.body.media_type, "The body media type")
        if op.accept:
            headers.set("accept", ", ".join(op.accept), "The accepted media types")
        applied = await self._authorize(op, headers, query)
        for spec in pending:
            if not any(_supplies(term, spec) for term in applied):
                raise _InputError(f"Parameter {spec.key} is required.")
        # Host-bound: the request keeps the configured origin and path prefix whatever the parameter values.
        if any(segment.lower() in _DOT_SEGMENTS for segment in path.split("/")):
            raise _InputError("Parameters must not move the request outside the configured base URL.")
        if op.method in ("GET", "HEAD", "TRACE") and content is not None:
            raise _InputError(f"A {op.method} request cannot have a body.")
        url = f"{self._base}{path}" + (f"?{'&'.join(query)}" if query else "")
        return _Prepared(url, headers.items(), content, replayable)

    async def _authorize(self, op: OperationSpec, headers: _HeaderBag, query: list[str]) -> tuple[SecurityTerm, ...]:
        """Applies the first credentialed security alternative whose credentials are all configured; an anonymous
        alternative is used only when none is, so optional authentication still sends credentials. A credential
        replaces any parameter sent under the same header or query name. Returns the terms applied."""
        configured = [terms for terms in op.security if all(self._credentials.get(term.scheme) is not None for term in terms)]
        alternative = next((terms for terms in configured if terms), None)
        if alternative is None:
            return ()
        for term in alternative:
            value = await _resolve(self._credentials[term.scheme])
            where = f"Credential {term.scheme}"
            if term.type == "basic":
                username = value.get("username") if isinstance(value, Mapping) else None
                password = value.get("password") if isinstance(value, Mapping) else None
                if not isinstance(username, str) or not isinstance(password, str) or ":" in username:
                    raise _InputError(f'{where} must be {{"username", "password"}} strings with no ":" in the username.')
                try:
                    token = base64.b64encode(f"{username}:{password}".encode("utf-8")).decode("ascii")
                except UnicodeEncodeError:
                    raise _InputError(f"{where} cannot be encoded as UTF-8.") from None
                headers.set("authorization", f"Basic {token}", where)
                continue
            if not isinstance(value, str) or value == "":
                raise _InputError(f"{where} must be a non-empty str.")
            if term.type == "bearer":
                headers.set("authorization", _header_value(f"Bearer {value}", where), where)
            elif term.location == "header" and term.name is not None:
                headers.set(term.name, _header_value(value, where), where)
            elif term.name is not None:
                # Like a header credential, a query credential is the only value sent under its name. Entries are
                # split into wire pairs first, since reserved expansion can put "&" and "=" in a value, and every
                # pair whose decoded name is the credential name or a deepObject member of it ("name[...]") is dropped.
                name = term.name
                kept = [pair for entry in query for pair in entry.split("&") if _pair_name(pair) != name and not _pair_name(pair).startswith(f"{name}[")]
                query[:] = [*kept, f"{_encode(name)}={_encode(value)}"]
        return alternative

    async def _attempt(self, op: OperationSpec, prepared: _Prepared, timeout: float, attempt: int) -> _Outcome:
        label = f"{op.method} {op.path}"
        request = TransportRequest(op.method, prepared.url, prepared.headers, prepared.content)
        try:
            status, headers, data = await _bounded(lambda state: self._exchange(request, state), timeout)
        except _TimedOut:
            return _Outcome(error=ApiTimeoutError(op.id, f"{label} timed out after {timeout:g} s.", attempt), retryable=True)
        except _TransportFailure as failure:
            error = ApiError("network", op.id, f"{label} {failure}.", attempt)
            error.__cause__ = failure.__cause__
            return _Outcome(error=error, retryable=True)
        body = _decode(status, headers, data, op.method)
        if 200 <= status < 300:
            # A success body must be one the operation documents, so the result matches its type.
            if op.success is not None:
                body = _as_documented(body, op.success)
            if body.malformed or (op.success is not None and body.kind not in op.success):
                described = "malformed JSON" if body.malformed else body.kind
                raise ApiError("decode", op.id, f"{label} returned a {described} body, which the operation does not document.", attempt)
            return _Outcome(value=body.value)
        # Declared: a documented status (an exact code, else a range, else default) with a body of a documented kind.
        code = str(status)
        entry = (
            next((candidate for candidate in op.errors if candidate.status == code), None)
            or next((candidate for candidate in op.errors if candidate.status == f"{code[0]}XX"), None)
            or next((candidate for candidate in op.errors if candidate.status == "default"), None)
        )
        if entry is not None:
            body = _as_documented(body, entry.kinds)
        # Malformed JSON is undeclared text.
        declared = entry is not None and body.kind in entry.kinds
        error = ApiHttpError(op.id, f"{label} returned HTTP {status}.", attempt, status, body.value, declared, headers)
        return _Outcome(error=error, retryable=status in _RETRY_STATUSES, retry_after=_retry_after(headers))

    async def _exchange(self, request: TransportRequest, state: _Abandonment) -> tuple[int, Headers, bytes]:
        try:
            response = await self._transport(request)
        except Exception as error:
            raise _TransportFailure("failed before a response was received") from error
        if not isinstance(response, TransportResponse):
            raise _TransportFailure(f"received {type(response).__name__} from the transport instead of a TransportResponse")
        state.hold(response)
        try:
            if state.abandoned:
                # The attempt was given up while a transport that ignored cancellation was still sending.
                return 0, Headers(), b""
            status = response.status
            if isinstance(status, bool) or not isinstance(status, int) or not 100 <= status <= 999:
                raise _TransportFailure(f"received an invalid status {status!r}")
            headers = Headers(response.headers)
            try:
                data = await _read_body(response.body, state)
            except Exception as error:
                raise _TransportFailure("failed while reading the response body") from error
            return status, headers, data
        finally:
            await state.close()

    def _observe(self, op: OperationSpec, error: ApiError, retryable: bool) -> None:
        hook = self._on_failure
        if hook is None:
            return
        meta = self._meta
        failure: FailureDetails = {"kind": error.kind, "retryable": retryable, "attempt": max(1, error.attempts)}
        if isinstance(error, ApiHttpError) and 100 <= error.status <= 599:
            failure["httpStatus"] = error.status
        event: ClientFailureObservation = {
            "schemaVersion": "apifn.client-failure/v1",
            "eventId": _event_id(),
            "occurredAt": _now(),
            "api": {"id": meta.api_id, "version": meta.api_version},
            "operation": {"id": op.id, "name": op.name, "method": op.method.lower(), "pathTemplate": op.path},
            "release": {
                "releaseId": meta.release_id,
                "catalogDigest": meta.catalog_digest,
                "sdk": {"target": meta.target, "package": meta.package_name, "version": meta.package_version},
            },
            "failure": failure,
        }
        # An observer never changes the call's outcome: what it raises is ignored, and an awaitable it returns is
        # awaited in the background with its failure ignored.
        try:
            result = hook(event)
            if inspect.isawaitable(result):
                _drain(result)
        except Exception:
            pass


def _text_body(body: str) -> bytes:
    try:
        return body.encode("utf-8", errors="strict")
    except UnicodeEncodeError:
        raise _InputError("Parameter body must be text UTF-8 can encode.") from None
